import type { ListeningScenario, Detail } from './listening-model.js';
const lectureRows = (values: string[]): Detail[] => values.map(value => {
  const [label, answer, reason] = value.split('|');
  return [label!, answer!, reason!];
});
const talk = (title: string, topic: string, band: number, style: ListeningScenario['style'], context: string, values: string[], closing: string): ListeningScenario => ({title, topic, band, style, context, details: lectureRows(values), closing});
export const lectureScenarios: ListeningScenario[] = [
talk('Why a loaf rises before it enters the oven','Food science',3,'note','Bread making is a useful example of a living process in an everyday kitchen. Flour and water do not simply become a loaf because they are heated. Before baking, the mixture changes as tiny organisms use available food, and the dough’s structure determines whether the resulting gas can remain inside.',[
'The living ingredient|yeast|It is added in a small quantity, but its activity changes the mixture during resting.',
'The food used by the organisms|sugars|Some are present already, while others become available as flour components break down.',
'The gas produced|carbon dioxide|It collects in small spaces and makes the dough increase in volume.',
'The network holding the gas|gluten|Mixing develops this structure, which stretches rather than letting every bubble escape immediately.',
'A helpful resting condition|warmth|Gentle warmth supports activity, but excessive heat can damage the living ingredient.',
'A stage that develops structure|kneading|The movement brings parts of the mixture together instead of merely changing its shape.',
'What slows the process|cold|A refrigerated dough can continue changing, but generally does so more slowly.',
'What ends the living activity|baking|The oven’s heat changes the dough into a firmer structure and stops the organisms functioning.',
'A common sign of insufficient resting|dense crumb|Fewer retained bubbles leave the interior more compact after the loaf is baked.',
'A useful record during an experiment|dough temperature|Room temperature alone does not show the condition of a mixture made with unusually cold water.',
],'A recipe’s clock time is therefore an estimate rather than a law. Observing volume and recording conditions can explain why the same ingredients behave differently on two kitchen days.'),
talk('How earthworms change a garden soil','Soil ecology',3.5,'summary','Earthworms are familiar animals, but their role is more interesting than simply being a sign of a good garden. They move material, create channels and interact with the living organisms in soil. Today we will follow those actions without assuming that every worm species behaves in exactly the same way.',[
'The material eaten near the surface|dead leaves|Soft plant remains are broken into smaller pieces rather than disappearing without a trace.',
'The place used by some species|burrows|These routes connect layers and can remain after the animal has moved elsewhere.',
'A resource entering through channels|air|The spaces change conditions for roots and other organisms in compact soil.',
'A liquid moving more easily|rainwater|Open channels may help water enter the ground rather than remain on the surface.',
'The deposited material|casts|This processed soil differs from a simple pile of untouched leaves.',
'An important seasonal danger|drought|Dry conditions can reduce activity or force animals deeper into suitable moisture.',
'A method for careful observation|soil sample|A small defined volume is more useful for comparison than collecting only visible animals.',
'The condition to keep consistent|sample depth|Different layers can contain different numbers, even at neighbouring points.',
'A plant response to investigate|root growth|The effect depends on the surrounding soil and should be measured rather than assumed.',
'A limit on a simple count|species differences|Two places with the same number may contain animals performing different roles.',
],'A worm count is one observation, not a complete soil-health score. A useful garden investigation also describes moisture, soil type and the method used to search.'),
talk('Why birds replace their feathers','Animal biology',4,'table','A bird’s feathers are living in origin but are not continuously repaired once fully grown. Flight, insulation and display all depend on their condition. Replacing feathers is therefore a routine biological process, although the timing and sequence differ between species and can affect what a bird is able to do.',[
'The replacement process|moulting|Old feathers are lost as new ones develop, rather than every feather lasting throughout life.',
'The main structural substance|keratin|It produces a lightweight structure but can still be damaged by repeated wear.',
'A function besides flight|insulation|The arrangement traps air close to the body and reduces loss of warmth.',
'A common source of damage|abrasion|Contact with surfaces gradually affects edges, especially when a bird moves through dense vegetation.',
'A resource needed for new growth|protein|Growing replacement material places demands on the bird’s diet.',
'A typical seasonal connection|breeding|Some species delay replacement until the demanding nesting period has finished.',
'A factor affecting the schedule|day length|Changing light provides a cue, though it does not explain every species’ timing alone.',
'A period of possible limitation|reduced flight|Certain birds lose enough flight feathers together that movement becomes temporarily restricted.',
'An observation used in field records|feather condition|Worn edges and new growth can help interpret a bird’s stage without handling it unnecessarily.',
'A reason to compare species separately|different strategies|A schedule suitable for one way of life may be unsuitable for another.',
],'Do not assume that a feather found on the ground proves injury. Routine replacement is common, and interpretation depends on species, season and the wider observations at the site.'),
talk('How a community rain barrel is prepared','Water management',4.5,'flow','We will examine a small rainwater installation used for garden irrigation. The purpose is not to create drinking water. The sequence removes large material, stores the collected water safely and directs it where plants can use it, while the supporting details address overflow and routine checks.',[
'First main stage|collect runoff|The inlet receives water from a suitable roof rather than from a dirty ground surface.',
'Second main stage|screen leaves|A removable mesh intercepts larger material before it reaches the storage space.',
'Third main stage|divert first-flow|The first brief flow carries much of the loose dust left between showers.',
'A required label|non-drinking water|Clear identification prevents a clean-looking container from being mistaken for a drinking supply.',
'A necessary overflow destination|permeable ground|Excess water should move away from the building without creating a slippery public path.',
'Fourth main stage|store water|A secure covered container reduces contamination and prevents easy access by small children.',
'Fifth main stage|open valve|The controlled outlet releases an appropriate amount instead of draining the whole container at once.',
'Sixth main stage|irrigate roots|Water reaches the soil close to the plants rather than being sprayed over paved surfaces.',
'A component requiring regular cleaning|mesh filter|An installation can lose efficiency when leaves accumulate even though the container itself is sound.',
'A condition affecting available volume|rainfall|A large container does not guarantee a constant supply during a dry period.',
],'A garden system should be inspected after heavy weather as well as on a routine schedule. The design is a starting point, while local rules and the actual roof materials still need checking.'),
talk('How shade changes the temperature of a pavement','Urban climate',5,'sentence','A shaded pavement often feels cooler, but the explanation involves more than the absence of direct sunlight. We will distinguish energy reaching the surface, heat stored in the material and the conditions experienced by a pedestrian. A simple comparison can reveal a mechanism without measuring the whole city’s climate.',[
'The incoming energy source|solar radiation|An exposed surface receives energy directly, while an object above it can interrupt that path.',
'The measured surface property|temperature|This differs from the surrounding air reading and should not be reported as if they were identical.',
'A factor controlling energy absorption|surface colour|A lighter surface can reflect more incoming light, although material properties also matter.',
'The source of moving shade|sun position|A fixed tree produces a changing pattern because the direction of incoming light changes.',
'A useful observation schedule|repeated readings|One cool morning measurement does not describe the surface during the hottest afternoon.',
'A control in the comparison|material type|Comparing stone under shade with dark asphalt in sunlight introduces more than one difference.',
'A device sensing surface energy|infrared thermometer|It provides a surface estimate without requiring the observer to place a probe inside the pavement.',
'A contextual record|cloud cover|Passing cloud can reduce radiation at both sites and alter the short-term comparison.',
'A pedestrian experience beyond heat|glare|A bright surface may change comfort even when its measured temperature is lower.',
'A possible evening effect|stored heat|A material warmed during the day can continue releasing energy after direct sunlight ends.',
],'A good comparison describes the material, time and weather. It should not promise that one colour or one tree position is the best solution for every public space.'),
talk('Reading a tree-ring sample cautiously','Environmental history',5.5,'note','Tree rings offer a visible record of growth, but reading them is more than counting lines. A ring reflects the conditions experienced by a particular tree, including competition and damage. We will consider what a sample can suggest, how it is compared with others and where an apparently simple interpretation can go wrong.',[
'The sampling tool|increment borer|It removes a narrow core without requiring the whole tree to be cut down.',
'The annual measurement|ring width|The measurement describes growth in that direction rather than the total size of the tree.',
'A common environmental influence|water availability|A dry period may limit growth, but the relationship depends on species and site.',
'A non-climatic influence|competition|Nearby plants can affect light and resources even when the weather remains similar.',
'The comparison procedure|cross-dating|Matching patterns across samples helps identify missing or incorrectly assigned years.',
'A possible recording problem|missing ring|Very limited growth can make a year difficult to recognise in a single core.',
'The upper measuring component|magnifying lens|It sits above the sample so the observer can inspect narrow boundaries without moving the core repeatedly.',
'The lower supporting component|sliding tray|The sample rests below the lens on this support, which moves in measured increments.',
'A useful site record|slope aspect|Orientation influences exposure and can help explain differences between nearby trees.',
'A limit on one sample|local conditions|A single tree does not automatically provide a complete climate record for a large region.',
],'The core becomes informative through comparison and context. Researchers distinguish the measured pattern from its possible causes, and they retain uncertainties rather than forcing every narrow ring into one explanation.'),
talk('Why wool clothing can remain warm when damp','Material science',6,'summary','Wool is often recommended for cool outdoor conditions, but a useful explanation should distinguish fibre structure from broad advertising claims. We will look at how fibres interact with water and air, then consider why the design of a garment matters as well as the material named on its label.',[
'The shape helping trap air|crimp|The fibre’s bends create spaces within the fabric rather than allowing every strand to lie flat.',
'The main insulating medium|air|The trapped layer limits heat transfer, provided the structure is not compressed excessively.',
'A property of the fibre surface|water resistance|It can slow initial wetting, but does not make a whole garment permanently waterproof.',
'The interior interaction|moisture absorption|Water can enter the fibre even when the outer surface still feels relatively dry.',
'A factor reducing insulation|compression|A tightly packed fabric loses some of the air spaces that contribute to warmth.',
'A garment feature affecting performance|fit|A material’s properties do not prevent cold air entering through a loose opening.',
'A suitable comparison condition|equal thickness|Different fabric depths would obscure whether the observed contrast comes from fibre type.',
'An important activity variable|sweat production|A hard climb creates a different moisture load from sitting still outdoors.',
'A limitation of the claim|not waterproof|Sustained rain can still wet clothing and change the wearer’s comfort.',
'A maintenance concern|drying conditions|A damp garment needs ventilation rather than being compressed in a sealed bag.',
],'The practical lesson is to evaluate a whole clothing system. Fibre properties matter, but thickness, fit, activity and weather determine whether a particular garment is suitable for the person wearing it.'),
talk('Following a seed through a seasonal dormancy cycle','Plant biology',6.5,'table','A seed does not always grow as soon as it has water. Dormancy can delay germination until conditions are more favourable, but it is not one identical mechanism across all plants. We will follow a simplified seasonal cycle and distinguish a viable resting seed from one that can no longer develop.',[
'The resting state|dormancy|The seed may remain capable of growth while not responding immediately to suitable-looking conditions.',
'A structural barrier in some species|seed coat|Its properties can limit water entry or prevent the embryo from expanding.',
'A seasonal cue|cold period|For certain species, exposure helps signal that a winter has passed.',
'A resource needed at germination|water|It enables internal processes to resume, but does not by itself guarantee that every barrier is removed.',
'A gas required by the embryo|oxygen|Waterlogged soil can restrict access even when moisture is abundant.',
'A method used to check viability|cut test|The internal condition can provide information, though the examined seed cannot then be planted normally.',
'A laboratory treatment|stratification|Controlled conditions reproduce part of the seasonal exposure instead of simply warming every seed.',
'A factor affecting emergence|burial depth|A seedling must reach the surface using limited stored resources.',
'A useful experiment record|germination count|The count needs a defined observation period rather than stopping when the first seed appears.',
'A reason to retain ungerminated seeds|delayed response|An early non-response is not always evidence that a seed is dead.',
],'Interpret the result for the species and treatment used. A method that helps one dormant seed may be irrelevant or damaging to another, so general advice must preserve those differences.'),
talk('The sequence of paper recycling in a small mill','Circular manufacturing',7,'flow','Paper recycling is often described as a single action, but a mill must separate usable fibres from contaminants and prepare a new sheet. We will follow a simplified operating sequence, with two supporting controls placed between stages. The process conserves material while still using water, energy and quality checks.',[
'First main stage|sort paper|Different grades and unwanted coated materials are separated before the feed reaches the wet process.',
'Second main stage|add water|The liquid loosens the old sheet structure so individual fibres can move.',
'Third main stage|separate fibres|Mechanical movement produces a suspension rather than leaving whole pieces of old paper intact.',
'A contaminant removed early|plastic fragments|They do not become part of the useful fibre suspension and can damage later equipment.',
'A controlled resource|water quality|Repeated reuse requires checking rather than assuming circulating water stays unchanged.',
'Fourth main stage|remove ink|The simplified demonstration separates printing material from the fibre mixture.',
'Fifth main stage|form sheet|A moving screen distributes fibres while allowing much of the water to drain.',
'Sixth main stage|dry paper|Controlled heat removes remaining moisture after the wet structure has been pressed.',
'A limit on repeated recycling|fibre shortening|Processing can gradually reduce strength, so new fibre may still be needed for some products.',
'A quality measure|sheet strength|A visually clean sheet is not sufficient if it tears too easily for its intended use.',
],'Recycling does not mean that every fibre can circulate forever without loss. A credible account includes the material limits and resource demands as well as the benefit of using recovered paper.'),
talk('How a field microphone measures a habitat soundscape','Acoustic ecology',7.5,'diagram','A habitat soundscape combines animal calls with wind, water and human activity. A field recorder can capture that mixture, but the recording depends on placement and equipment. We will examine a simple mounted device and then consider how a researcher avoids treating a change in recording conditions as a change in wildlife.',[
'The recorded information|sound pressure|The signal represents changes at the device, not a direct count of animals.',
'A timing rule|fixed intervals|A repeatable schedule reduces differences caused by choosing only dramatic moments.',
'A weather interference|wind noise|Air movement across the sensor can obscure quieter biological sounds.',
'A protective accessory|foam windshield|It reduces some disturbance without eliminating every environmental influence.',
'A position to standardise|recording height|Moving the device can change which sounds dominate even at the same site.',
'A useful contextual entry|rainfall|Water can create sound and alter animal activity, so it belongs in the field record.',
'The upper sensing component|microphone|It sits above the support and converts pressure changes into a recordable signal.',
'The lower supporting component|mounting pole|This vertical support below the sensor fixes the height and helps prevent movement.',
'A precaution for publication|voice screening|A background conversation may be recognisable even when no person was the intended subject.',
'A limit of a simple index|source mixture|An increase in acoustic energy can come from traffic rather than more biological activity.',
],'A sound recording is evidence whose conditions must be documented. It can reveal useful patterns, but interpretation requires attention to sources, weather and the assumptions behind any numerical summary.'),
talk('Using thermal images to inspect a historic building','Building science',8,'sentence','Thermal imaging creates an appealing picture of a building, but the colours do not directly label defects. A surface’s emitted energy depends on its material and surroundings as well as temperature. We will consider how an inspector combines the image with construction knowledge and a record of the conditions during the visit.',[
'The detected energy|infrared radiation|The camera senses a band outside ordinary visible light rather than photographing coloured heat directly.',
'A material property affecting interpretation|emissivity|Different surfaces can produce different signals at the same physical temperature.',
'A misleading influence|reflected radiation|A shiny surface may show energy arriving from its surroundings rather than only its own emission.',
'A required contextual record|weather conditions|Recent sunlight, wind and rain can affect the pattern visible on an exterior wall.',
'A helpful indoor-outdoor condition|temperature difference|Without a useful contrast, some heat-flow patterns are difficult to distinguish.',
'A possible structural explanation|thermal bridge|A conducting connection can create a local pattern without indicating an air leak.',
'A supporting investigation|construction drawing|The image can be compared with known structural elements rather than interpreted through colour alone.',
'A precaution during comparison|consistent settings|Changing the display scale can make a similar pattern appear more dramatic.',
'A limit on diagnosis|multiple causes|A cold-looking patch may have more than one credible explanation.',
'A useful report feature|stated uncertainty|The inspector should explain what the observation supports and what needs another check.',
],'The image is a starting point for interpretation, not an automatic repair specification. A responsible report connects each proposed explanation to evidence and avoids presenting a vivid colour as proof of one cause.'),
talk('How a bee communicates a distant food location','Animal communication',5,'note','Honeybee communication provides an example of information encoded in movement. A returning forager does not draw a map for another bee. Instead, features of its behaviour relate to direction and distance, and the receiving insects use that information alongside other cues when searching outside the hive.',[
'The communicating individual|forager|It has visited the resource and returns to the colony with information from that trip.',
'The movement pattern|waggle dance|A repeated central run is connected with the location of a resource.',
'The reference for direction|sun position|The meaning of an angle depends on a reference rather than a fixed compass word.',
'A feature related to distance|run duration|A longer central movement generally signals a more distant location in the simplified account.',
'An additional identifying cue|flower scent|Other bees can use it when searching near the indicated area.',
'A factor changing the reference|time|The sun’s position shifts, so communication cannot be interpreted without considering when it occurs.',
'A method used by researchers|video analysis|Repeated recordings allow movement features to be compared carefully.',
'A possible environmental difficulty|cloud cover|Outdoor orientation can be affected even though the hive communication remains observable.',
'A caution about the message|approximate location|The signal guides a search rather than guaranteeing a precise landing point.',
'A useful experimental control|resource distance|The researcher changes a known location while recording the corresponding movement.',
],'The behaviour is informative without being identical to human language. A careful explanation identifies the relationship being tested and avoids treating every movement as a complete sentence.'),
talk('Why lichen can reveal changes in an urban environment','Urban ecology',5.5,'summary','Lichens combine organisms in a close association and often grow on surfaces people overlook. Their presence can support environmental observations, but it is not a single universal pollution meter. We will consider what they need, how a survey is organised and why the surface itself matters to interpretation.',[
'The visible growing surface|tree bark|It provides a habitat, but its properties differ between tree species.',
'The light-using partner|alga|It contributes food produced through photosynthesis within the association.',
'The structural partner|fungus|It creates much of the visible body and influences the shared environment.',
'A source of water|rainfall|The organisms take up moisture from their surroundings rather than using a plant’s root system.',
'A surface property to record|acidity|A difference in the host surface can affect which forms grow there.',
'A survey method|sampling grid|Defined squares support comparison instead of recording only conspicuous patches.',
'A condition to standardise|trunk height|Moving the grid changes light and exposure as well as the area being observed.',
'A possible pollution influence|nitrogen compounds|Different forms can respond differently, so total coverage alone may conceal a change.',
'A reason for repeated surveys|slow response|A community may reflect a longer history rather than only the weather on survey day.',
'A limit on one interpretation|habitat differences|Absence can have several causes and is not automatically proof of severe pollution.',
],'Record the host and method alongside the result. The observation becomes stronger through repeated comparable surveys and an explanation of the alternative influences that were considered.'),
talk('How a cave deposit grows from moving water','Geological processes',6,'table','Cave deposits can look fixed and permanent, but their forms result from water moving and changing chemically. We will follow a simplified account of a drip deposit. Its shape depends on where water arrives, what it carries and what happens when the water meets the cave air.',[
'The dissolving liquid|rainwater|It acquires dissolved gases and interacts with rock during its underground journey.',
'The common host rock|limestone|The simplified example concerns a material that can dissolve under the relevant conditions.',
'The transported substance|calcium carbonate|It can later be deposited when the water’s chemical balance changes.',
'A process at the cave entrance|gas loss|Water exposed to a different atmosphere can release part of its dissolved gas.',
'The ceiling formation|stalactite|Material accumulates where repeated drops leave the roof.',
'The floor formation|stalagmite|Deposits build where water lands below, rather than growing down from the ceiling.',
'A controlling rate|drip frequency|The interval changes how much water arrives and how long it interacts with a surface.',
'A potential human disturbance|skin oils|Touching can alter a delicate growing surface even when no visible piece breaks off.',
'A record held in some layers|past conditions|The deposit may contain information about its formation environment when interpreted carefully.',
'A limit on casual dating|uneven growth|A larger formation is not necessarily a simple measure of age.',
],'The account is intentionally simplified. Researchers use measurements and sampling permissions to investigate a deposit, while visitors should avoid touching or removing material from a living cave system.'),
talk('How an air-particle monitor records a roadside sample','Air quality',6.5,'diagram','A roadside monitor can help reveal how conditions change through the day, but its result depends on what enters the instrument and where the device is placed. We will inspect a simple elevated sampling unit and distinguish a local measurement from a complete account of everyone’s exposure across a town.',[
'The measured material|airborne particles|The device records a defined size range rather than every gas and dust component.',
'A location variable|road distance|A measurement close to traffic may differ from one behind a building.',
'A timing approach|continuous sampling|A sequence shows variation that a single brief reading would miss.',
'A meteorological influence|wind direction|Air arriving from another source can change the sample independently of traffic at the road.',
'A necessary maintenance action|inlet cleaning|Deposits can obstruct the entry and affect what the instrument receives.',
'A comparison precaution|matching intervals|Two hourly averages should cover the same period before their difference is interpreted.',
'The upper sampling component|air inlet|It projects above the housing so the sample can enter without being drawn from the ground surface.',
'The lower supporting component|support column|The column below the sampling unit maintains the stated height.',
'A useful quality check|reference comparison|A nearby established device can help reveal a systematic measurement difference.',
'A limit on the conclusion|local exposure|One position cannot represent every street, building interior or journey.',
],'Describe the placement and instrument range with the values. The monitor is useful because its conditions are known, not because any precise number automatically stands for the whole community.'),
talk('Following a used glass bottle through remanufacturing','Material cycles',7,'flow','A recovered glass bottle can become feedstock for a new container, but the collection stage alone does not complete that transformation. We will follow the main operating sequence and then identify the contamination and quality issues that determine whether the resulting material meets its intended purpose.',[
'First main stage|collect bottles|A defined collection stream helps avoid mixing glass with unsuitable household material.',
'Second main stage|separate colours|Colour categories matter for the appearance and specification of the new container.',
'Third main stage|remove contaminants|Metal pieces and ceramics behave differently during later heating.',
'A particularly troublesome material|ceramics|A small fragment can remain incompatible with the surrounding glass after processing.',
'A resource still required|energy|Using recovered material does not remove the need for a controlled high-temperature process.',
'Fourth main stage|crush glass|The resulting small pieces can be handled as a consistent feedstock.',
'Fifth main stage|melt mixture|Recovered material is heated under conditions suitable for forming a new container.',
'Sixth main stage|shape bottles|The hot material enters a mould and is cooled according to the required specification.',
'A final quality measure|wall thickness|A bottle that looks complete may still be unsuitable if its structure is inconsistent.',
'A limit on collection claims|contamination losses|Not every collected item becomes usable material in the final product.',
],'A credible recycling account follows the material beyond the collection bin. It includes rejected contamination, remaining resource use and the quality requirements of the new container.'),
talk('How night lighting affects an insect survey','Environmental observation',7.5,'sentence','Night surveys often use light to attract insects, but the method itself changes what is observed. A trap provides a sample shaped by the equipment and conditions, not a complete inventory of every insect living nearby. We will examine those influences and consider how researchers compare sites responsibly.',[
'The attraction device|light trap|It draws some insects towards a collecting point instead of observing all movement neutrally.',
'A variable in the equipment|wavelength|Different emitted light can attract different groups rather than only changing the total number.',
'A surrounding influence|background lighting|A bright neighbouring source may compete with the survey device.',
'A weather record|night temperature|Activity can change when conditions become colder even with identical equipment.',
'A schedule to standardise|operating hours|A longer run provides more opportunity to collect insects and cannot be compared casually.',
'A precaution for comparison|same lamp|Changing equipment between sites would mix a location effect with a sampling effect.',
'A classification concern|identification uncertainty|A damaged or unfamiliar specimen should not be assigned confidently just to complete the table.',
'A welfare consideration|release method|The survey should follow its approved handling procedure rather than retaining every specimen unnecessarily.',
'A limit on abundance estimates|sampling bias|A count reflects attraction and activity as well as the population present.',
'A stronger design feature|repeated nights|Several comparable observations reduce dependence on one unusual evening.',
],'State how the sample was produced before interpreting a count. A repeated controlled method can reveal a useful pattern while still acknowledging that it does not measure every species equally.'),
talk('How pollen moves between wind-pollinated plants','Plant reproduction',8,'note','Wind pollination is sometimes portrayed as a less precise alternative to an animal carrying pollen. Its success depends on the structure and timing of the plant as well as the movement of air. We will consider both production and capture, while separating the pollen released from the pollen that reaches a compatible target.',[
'The transported reproductive material|pollen|Large quantities may be released, but only a fraction reaches a useful destination.',
'A structure exposed to airflow|anther|Its position can influence how readily grains leave the plant.',
'The receiving structure|stigma|Its form affects capture rather than actively guiding every grain through the air.',
'A timing advantage|synchronised flowering|Overlapping release and receptivity increase the opportunity for transfer between compatible plants.',
'A vegetation influence|canopy density|Obstacles change air movement and can intercept grains before they reach another plant.',
'A weather constraint|rain|Wet conditions may alter release and remove grains from the air.',
'A sampling device|pollen slide|The collected grains indicate airborne presence at a known place and time.',
'A distinction in interpretation|release versus capture|A high airborne count does not directly measure successful fertilisation.',
'A possible human effect|allergic response|Exposure affects people differently and is not determined by grain count alone.',
'A limitation of one station|spatial variation|A point record does not describe every street or height within the surrounding area.',
],'The system is probabilistic but structured. A useful explanation connects plant form, timing and airflow without implying that every released grain is either wasted or guaranteed to produce a seed.'),
talk('Why stored vegetables need controlled humidity','Food storage',4.5,'summary','Fresh vegetables continue to change after harvest. They lose water, exchange gases and may be damaged by unsuitable storage conditions. We will examine a simple vegetable store and distinguish preserving appearance from maintaining a safe usable product, because a firm-looking item is not automatically free of every problem.',[
'Continuing biological process|respiration|Harvest does not immediately stop the internal activity of a living plant part.',
'The main visible loss|water|A declining amount can make leaves or roots lose firmness.',
'A useful environmental control|humidity|The surrounding moisture condition affects how quickly water moves away from the produce.',
'A danger of excess surface moisture|mould|Wet surfaces can create conditions favourable to unwanted growth.',
'A temperature precaution|avoid freezing|Some vegetables are damaged by ice even though a cool store slows other changes.',
'A handling problem|bruising|Damage can make an item deteriorate faster than an apparently similar uninjured one.',
'A storage arrangement|air circulation|Spaces between containers prevent a tightly packed stack from developing different local conditions.',
'A routine observation|condition check|The store should be inspected rather than assuming that its initial setting remains suitable.',
'A stock-management principle|first-in first-out|Older acceptable produce is used before newer deliveries to reduce unnecessary waiting.',
'A reason for separate storage|different requirements|A single humidity and temperature combination does not suit every type equally.',
],'Storage advice must name the produce and the intended period. Better conditions can slow deterioration, but they do not reverse physical damage or turn unsafe food into a suitable meal.'),
talk('How a rooftop garden manages excess water','Urban design',5,'table','A rooftop garden adds a living layer to a building, but its water system must work with the roof’s structural and waterproofing functions. We will look below the plants to understand how water is retained, filtered and released, rather than treating the surface greenery as the complete installation.',[
'The upper living layer|vegetation|Plants contribute to the system, but their survival depends on the layers below.',
'The growing material|substrate|It is selected for weight and water behaviour rather than being ordinary garden soil.',
'A separating layer|filter sheet|It limits the movement of fine material into the drainage space.',
'The water-moving layer|drainage mat|Channels provide a route when retained water exceeds what the system can hold.',
'The protected building surface|waterproof membrane|The planting system must not compromise the roof’s barrier against leaks.',
'A quantity checked by engineers|saturated weight|A dry installation can be much lighter than the same system holding water.',
'A maintenance point|outlet|Leaves or loose material can block the route even when the garden looks healthy.',
'A weather challenge|heavy rainfall|Retention has a limit, so excess flow needs a planned destination.',
'A plant-selection factor|drought tolerance|A shallow growing layer may dry quickly during a long rainless period.',
'A limit on the benefit|finite storage|A green roof can alter runoff without retaining every storm permanently.',
],'The system needs structural review and maintenance. Its visible plants are useful, but they cannot replace a safe load assessment, a functioning waterproof barrier and clear drainage routes.'),
talk('Why a river forms an outer-bank bend','Physical geography',5.5,'sentence','A river bend provides a visible connection between water movement and changing land. The pattern is not static: erosion and deposition can move the channel over time. We will use a simplified bend to explain where material is removed, where it accumulates and why real channels may depart from the neat classroom picture.',[
'The faster main flow|outer bend|The water’s path tends to bring greater erosive action towards this side.',
'The removal process|erosion|Material can be carried away from the bank and bed when the flow has sufficient force.',
'The slower accumulation area|inner bend|Reduced movement allows some transported material to settle.',
'The accumulation process|deposition|The new material can build a visible bar along the inside of the curve.',
'A transported material|sediment|Its size influences how readily it moves or settles under the available conditions.',
'A factor stabilising a bank|plant roots|They can hold material together, although their effect depends on the bank and vegetation.',
'A major change event|flood|Unusual flows may alter the channel more rapidly than ordinary daily movement.',
'A field measurement|bank position|Repeated records show movement rather than relying on one photograph.',
'A comparison reference|fixed marker|The observer needs a stable point that is not itself moving with the bank.',
'A limit on the simple model|local geology|Rock, artificial structures and bank materials can change the expected pattern.',
],'The model helps organise observation, but it is not a substitute for field evidence. A useful survey records changes through time and notes structures or materials that may alter the flow.'),
talk('How a small solar weather station is powered','Field instrumentation',6,'diagram','A remote weather station needs energy even when nobody is present to replace a battery. A small solar-powered design combines collection and storage, but its operation depends on exposure and demand. We will examine the upper and lower parts of a mounted station before considering how researchers verify that missing data do not conceal a power problem.',[
'The electrical supply source|sunlight|The device harvests energy locally rather than relying on a permanent mains connection.',
'The storage component|battery|It provides power when incoming light is insufficient for immediate operation.',
'A period of increased risk|winter|Shorter days and low sun can reduce the available energy.',
'A placement concern|shade|A nearby branch can obstruct the collector even when the wider site appears open.',
'A controlled demand|sampling frequency|More frequent measurements can increase the energy required by the station.',
'A routine record|battery voltage|A declining value may explain gaps that would otherwise look like a sensor fault.',
'The upper energy component|solar panel|It sits at the top of the mounted assembly with a clear view of incoming light.',
'The lower supporting component|support post|This vertical post below the panel keeps the assembly at its surveyed position.',
'A maintenance task|surface cleaning|Dust or debris can reduce incoming energy without breaking an electronic component.',
'A limit on data interpretation|power interruptions|Missing readings should not be treated automatically as calm or unchanged weather.',
],'A field station’s data are stronger when its operating condition is documented. The absence of a value needs an explanation, especially when weather and energy supply can change together.'),
talk('Preparing a plant sample for a herbarium record','Botanical archives',6.5,'flow','A herbarium record preserves a plant sample together with information about where and when it was collected. The object and the record support one another. We will follow the preparation sequence while noting permissions and labels, because a neatly flattened specimen without context has much less research value.',[
'First main stage|select specimen|The collector chooses material that can show identifying features without taking an unnecessarily large amount.',
'Second main stage|record location|The site information is written while the collection context is still clear.',
'Third main stage|arrange plant|Leaves and flowers are positioned so useful surfaces remain visible.',
'A requirement before collecting|landowner permission|Access to a path does not automatically authorise removing plants beside it.',
'A label detail beyond place|collection date|Seasonal timing may be important when comparing records or identifying a flowering stage.',
'Fourth main stage|press sample|The material is held flat between suitable absorbent layers.',
'Fifth main stage|dry material|Moisture is removed under controlled conditions to reduce later deterioration.',
'Sixth main stage|mount specimen|The prepared object is secured with its identifier and associated record.',
'A final check|label match|The specimen and information must not be separated or swapped during preparation.',
'A conservation limit|protected species|Some plants cannot be collected through the ordinary teaching procedure.',
],'The collection is a documented archive, not simply a group of decorative plants. Careful labels, permissions and handling preserve the evidence that later users need to interpret a specimen.'),
talk('How salt affects the movement of coastal groundwater','Coastal hydrology',7,'note','Fresh groundwater near a coast interacts with saline water, and the boundary is not a rigid wall. Pressure, density and extraction all matter. We will use a simplified cross-section to discuss the balance, while avoiding the assumption that one shoreline position or one water sample describes the entire underground system.',[
'The inland supply|recharge|Rain entering the ground can contribute to the fresh-water part of the system.',
'A property distinguishing saline water|density|Dissolved salts change how the water behaves in the simplified balance.',
'A process altering the balance|pumping|Extraction can reduce fresh-water pressure near a well.',
'The unwanted movement|saline intrusion|Saltier water may move into a zone used for a fresh-water supply.',
'A coastal timing influence|tides|Changes in the external water level can affect near-shore conditions.',
'A monitoring measure|electrical conductivity|It provides an indicator related to dissolved ions, interpreted alongside other information.',
'A sampling concern|well depth|Different levels can reveal different conditions within the same general location.',
'A comparison requirement|consistent interval|A tide-related change can be mistaken for a longer trend if timing is ignored.',
'A management response|reduce extraction|The appropriate action depends on the local system rather than one universal pumping rule.',
'A limit on the diagram|geological variation|Layers and connections underground can complicate the simplified interface.',
],'A useful monitoring programme describes depth, timing and extraction history. The diagram explains a mechanism, but a real supply decision requires evidence about the local aquifer and the people depending on it.'),
talk('Why an ancient pigment changes under museum lighting','Conservation science',7.5,'summary','A museum colour is not always a stable property waiting to be photographed. Pigments, binders and lighting can interact, and past treatment may complicate the pattern. We will consider how conservators distinguish a visible change from its possible mechanism and why documenting exposure is essential before deciding on intervention.',[
'The colouring material|pigment|Its behaviour depends on composition rather than only the colour name used in a catalogue.',
'The holding medium|binder|It influences the surface and may itself change as the object ages.',
'A possible driving factor|light exposure|Damage can relate to both the intensity and the duration of illumination.',
'A cumulative measure|exposure dose|A short bright period and a longer dim period need to be considered in relation.',
'A testing approach|controlled sample|An expendable prepared sample can support comparison without testing recklessly on the original.',
'A documentation method|colour measurement|A repeatable instrument reading can reveal change that casual memory does not capture reliably.',
'A confounding history|previous treatment|A coating applied earlier can alter the present appearance and response.',
'A preventive measure|reduced illumination|Management can limit further change without immediately removing material from the object.',
'A caution about photographs|display settings|Screen and camera differences can make apparent colour change unrelated to the original.',
'A decision principle|minimal intervention|Treatment should be justified by evidence and the object’s needs, not the desire for a brighter image.',
],'The aim is not automatically to restore an imagined original colour. Conservation decisions balance evidence, stability and significance while stating what the available measurements cannot determine.'),
talk('How a porous pavement changes storm runoff','Civil engineering',8,'table','A porous pavement is designed to let water move through spaces rather than flow entirely across the top. Its performance depends on the underlying layers and their connection with the ground. We will distinguish infiltration, temporary storage and final drainage, because those processes are often combined in a vague claim that the surface simply absorbs rain.',[
'The entry route|surface pores|Openings let water pass below the visible walking or driving surface.',
'The temporary holding layer|aggregate reservoir|Spaces between coarse material store water before it leaves the system.',
'The downward process|infiltration|Water enters suitable ground when its condition and the design permit.',
'An alternative outlet|underdrain|Some installations route water through a pipe when the underlying ground cannot accept it sufficiently.',
'A performance threat|sediment clogging|Fine material can obstruct the entry even if the deeper reservoir remains empty.',
'A maintenance action|vacuum cleaning|The method removes material from the pores rather than washing it further into the system casually.',
'A design variable|ground permeability|The soil’s behaviour affects whether storage can empty between storms.',
'A structural consideration|traffic load|A water-managing surface must still support its intended use safely.',
'A monitoring distinction|entry versus outflow|Water disappearing from the surface does not show where it finally goes.',
'A limit on capacity|storm intensity|A design has finite entry and storage rates rather than handling every possible event.',
],'Performance should be described as a sequence with measurable limits. A successful surface on one site is not proof that the same depth and outlet arrangement will suit every ground condition.'),
talk('Why sleep timing can change after a long journey','Human biology',5,'sentence','Travelling across time zones changes the relationship between a person’s internal timing and the local day. Feeling tired is only one effect, and recovering is not simply a matter of deciding to sleep at the advertised hour. We will examine cues that influence timing without offering one prescription for every traveller.',[
'The internal timing system|body clock|It coordinates patterns that continue even when a person is not looking at a watch.',
'The external cue|light|Exposure at different times can influence how internal timing shifts.',
'A travel-related mismatch|time-zone change|The local schedule may no longer coincide with the traveller’s previous rhythm.',
'A common symptom|daytime sleepiness|A person can feel tired when the local routine expects them to be active.',
'A factor affecting adjustment|travel direction|Moving east and moving west need not create an identical shift.',
'A behaviour to record|sleep timing|The actual period matters more than a statement that the traveller slept badly.',
'An additional influence|meal schedule|Daily routines can change alongside the light environment.',
'A relevant individual difference|chronotype|People’s usual timing preferences vary and can influence the experience.',
'A distinction in interpretation|sleep loss|Missing hours during travel is not the same mechanism as a shifted internal rhythm.',
'A limit on simple advice|individual variation|The route, schedule and person’s circumstances affect what is appropriate.',
],'A useful account distinguishes accumulated lack of sleep from timing mismatch. Practical advice should consider the journey and individual circumstances rather than promise that one rule works for everyone.'),
talk('How fungal networks interact with forest roots','Forest ecology',5.5,'note','Some fungi form close associations with plant roots. The relationship involves exchanges and can affect how a plant obtains resources, but a simple image of every tree sharing equally is misleading. We will consider the structures involved, the resources moving and the evidence required to interpret an observed connection.',[
'The plant contact point|roots|The association occurs below ground rather than beginning on the tree’s leaves.',
'The fine fungal structures|hyphae|They extend through soil and can reach spaces beyond the root surface.',
'A resource obtained from soil|nutrients|The particular contribution depends on the organisms and surrounding conditions.',
'A resource supplied by the plant|carbon compounds|Photosynthesis can provide material used by the associated fungus.',
'A condition affecting the relationship|soil moisture|Availability changes both plant demand and the movement of resources.',
'A research method|tracer experiment|A labelled substance helps investigate movement rather than inferring it from proximity alone.',
'A necessary comparison|unconnected control|The design needs to distinguish movement through the association from other possible routes.',
'A source of complexity|species differences|A relationship observed in one pairing may not have the same balance in another.',
'A misleading assumption|equal sharing|A connection does not prove that resources are distributed evenly between all participants.',
'A limit on a photograph|hidden exchange|A visible structure alone does not establish the amount or direction of transfer.',
],'The association is scientifically important without being a simple story of universal cooperation. Researchers need evidence for movement, context for its benefit and caution about generalising from one experimental pairing.'),
talk('How a museum humidity logger is checked','Collection care',6,'diagram','A humidity logger is a small instrument, but its readings can influence important decisions about collection care. The sensor and its installation need checking before a graph is treated as evidence of a room problem. We will inspect a simple elevated unit and then consider comparison, placement and the meaning of a brief excursion.',[
'The measured condition|relative humidity|The value depends on moisture in relation to temperature, not just the total water present.',
'A related reading|air temperature|It helps explain a humidity change that might otherwise appear mysterious.',
'A placement to avoid|direct sunlight|Heating the device can create an unrepresentative local reading.',
'A comparison procedure|reference check|The logger is placed near a trusted instrument under stable conditions.',
'A sampling setting|recording interval|Long gaps may miss a brief change, while very frequent entries increase data volume.',
'A contextual event|door opening|A short exchange of air can affect the reading without proving a permanent room failure.',
'The upper measuring component|humidity sensor|It is exposed above the housing so air can reach the sensing area.',
'The lower supporting component|mounting bracket|The bracket below the unit fixes its position away from a misleading contact surface.',
'A record of instrument condition|calibration history|A drift in the device needs to be considered before changing the room controls.',
'A limit on one location|spatial variation|Conditions near a wall or case may differ from the centre of the gallery.',
],'A graph is stronger when the instrument history and local events are recorded. A brief peak deserves investigation, but it should not automatically be interpreted as evidence that every object experienced the same condition.'),
talk('Preparing a clean water sample for field analysis','Environmental monitoring',6.5,'flow','A water sample is useful only when the collection and handling support the question being asked. The sequence I will describe concerns a prepared field exercise with approved equipment, not the collection of unknown water for drinking. Supporting notes identify the permissions and records that preserve the sample’s meaning.',[
'First main stage|choose point|The location should match the investigation rather than the easiest place to reach.',
'Second main stage|prepare container|The approved vessel is checked and handled according to the selected analysis method.',
'Third main stage|collect water|The collector follows the defined depth and avoids disturbing nearby sediment unnecessarily.',
'A required safety condition|safe access|A useful location is not acceptable if reaching it puts the collector at risk.',
'A contextual label|sampling time|Conditions can change through a day, so the collection moment belongs with the sample.',
'Fourth main stage|seal container|The sample is closed promptly to reduce contamination during handling.',
'Fifth main stage|record conditions|Weather and visible flow help later interpretation without replacing the actual measurement.',
'Sixth main stage|transport sample|The method specifies timing and temperature rather than allowing indefinite storage.',
'A quality-control item|blank sample|It can help identify contamination introduced by the equipment or process.',
'A limit on interpretation|single location|One container does not represent every part of a changing water body.',
],'Every analysis method has its own handling requirements. The field record should describe what was actually done, including departures from the plan, rather than making the procedure look perfect after the fact.'),
talk('Why a volcanic ash layer can connect distant records','Earth history',7,'summary','An ash layer can provide a useful link between records from different places, but appearance alone is not enough to establish that they came from the same eruption. We will consider transport, preservation and chemical comparison, while distinguishing the event that produced the ash from the later processes that may move it.',[
'The original source|eruption|Material is released during an event rather than forming independently in every sediment record.',
'The transport mechanism|wind|Direction and strength affect where particles travel and how much reaches a site.',
'A recognisable microscopic material|glass shards|Their form can support identification, although shape is not the only evidence.',
'A stronger comparison|chemical fingerprint|Composition helps distinguish similar-looking layers from different sources.',
'A preservation setting|lake sediment|A deposited layer can remain within a sequence that records later accumulation.',
'A disturbance to consider|reworking|Older material may be moved into a younger deposit instead of remaining where it first fell.',
'A sampling precaution|clean tools|Contamination between layers could create a false mixture of signatures.',
'A useful contextual record|layer position|The relationship to neighbouring deposits supports interpretation of the sample.',
'A limit on a visual match|similar appearance|Two pale bands do not automatically identify the same eruption.',
'A value of a secure correlation|shared time-marker|The connection can help compare changes in records that otherwise use different dating evidence.',
],'The correlation is strongest when several lines of evidence agree. A useful time marker should be justified through composition and context, not chosen because two layers look conveniently alike.'),
talk('How a fish passage responds to changing river flow','River engineering',7.5,'table','A fish passage is intended to support movement around a barrier, but its success depends on the species, their life stage and the flow conditions. We will compare features of a simplified stepped route and consider why counting fish at one entrance does not prove that the whole journey has been completed.',[
'The route’s purpose|upstream movement|It provides an alternative around a barrier that interrupts the ordinary channel.',
'A structural feature|resting pools|These spaces reduce the need for continuous effort through the entire route.',
'A hydraulic condition|water velocity|A current manageable by one species may prevent another from progressing.',
'A seasonal influence|migration timing|The route must function when the relevant fish actually attempt the journey.',
'A location affecting discovery|entrance position|Fish need to find the opening before the internal design can help them.',
'A possible observation method|video count|The record should define which part of the route is visible.',
'A stronger outcome|completed passage|Entering the first section is different from emerging beyond the barrier.',
'A variation between users|body size|Swimming capacity and the spaces used can differ across life stages.',
'A maintenance concern|debris blockage|The route can become unusable even when the original design remains unchanged.',
'A limit on one season’s result|flow variation|A successful period does not guarantee identical performance under another water condition.',
],'Describe the species and flows with the outcome. A passage is a route to be found and completed, not merely a structure whose presence proves that a barrier has been resolved.'),
talk('How a soil seed bank complicates restoration decisions','Restoration ecology',8,'sentence','A restored habitat may contain seeds left by vegetation that is no longer visible. That hidden bank can support recovery, but it can also produce an unexpected response when soil is disturbed. We will distinguish the seeds present, those still viable and those that actually emerge under a particular set of conditions.',[
'The hidden store|seed bank|It includes material accumulated through earlier periods rather than only the plants currently growing.',
'A property needed for future growth|viability|A visible seed may no longer be capable of producing a plant.',
'A condition delaying emergence|dormancy|The seed can remain alive without responding to the immediate environment.',
'A disturbance affecting response|soil movement|Bringing a buried seed closer to the surface can change its exposure to cues.',
'A common emergence cue|light|The effect depends on species and does not mean every buried seed behaves identically.',
'A testing approach|germination trial|Controlled conditions reveal one part of the bank’s potential rather than every possible future response.',
'A sampling requirement|defined depth|Different layers may preserve different periods and conditions.',
'A historical influence|previous land-use|Past cultivation or disturbance can affect what survives beneath the present vegetation.',
'A distinction in a report|presence versus emergence|The number counted and the number growing answer related but different questions.',
'A limit on prediction|conditional response|Future weather and disturbance help determine which viable seeds become visible plants.',
],'Restoration planning should treat the bank as evidence with a history and conditions. A single trial is useful, but it cannot guarantee the exact community that will appear after every management action.'),
];
